parameters.inputSchema:
{
  "type": "object",
  "properties": {
    "category": { "type": "string", "enum": ["access", "hardware", "software", "network", "email", "security", "other"], "description": "The single best category for the ticket" },
    "priority": { "type": "string", "enum": ["P1", "P2", "P3", "P4"], "description": "P1 = many users blocked or business stopped. P2 = one user fully blocked or time critical. P3 = degraded but can work. P4 = question or minor request." },
    "affected_system": { "type": "string", "description": "The system or application named in the ticket, or unknown" },
    "summary": { "type": "string", "description": "One plain sentence describing the problem" },
    "confidence": { "type": "number", "description": "How sure you are about category and priority, from 0 to 1" },
    "needs_human": { "type": "boolean", "description": "true if a person must review before any action is taken" },
    "reasoning": { "type": "string", "description": "One or two sentences explaining the category and priority" }
  },
  "required": ["category", "priority", "affected_system", "summary", "confidence", "needs_human", "reasoning"]
}

parameters.jsCode:
const PROMPT_VERSION = "v2";
const CATEGORIES = ["access", "hardware", "software", "network", "email", "security", "other"];
const PRIORITIES = ["P1", "P2", "P3", "P4"];
const CONFIDENCE_GATE = 0.7;

const raw = $json.output || {};
const ticket = $("Receive Ticket Fields").item.json;
const problems = [];

if (!CATEGORIES.includes(raw.category)) problems.push("category not in allowed list");
if (!PRIORITIES.includes(raw.priority)) problems.push("priority not in allowed list");

let confidence = Number(raw.confidence);
if (!Number.isFinite(confidence) || confidence < 0 || confidence > 1) {
  problems.push("confidence not between 0 and 1");
  confidence = 0;
}

const valid = problems.length === 0;
const category = CATEGORIES.includes(raw.category) ? raw.category : "other";
const priority = PRIORITIES.includes(raw.priority) ? raw.priority : "P3";

const humanReasons = [];
if (!valid) humanReasons.push("model output failed validation");
if (raw.needs_human === true) humanReasons.push("model asked for review");
if (priority === "P1") humanReasons.push("P1 ticket");
if (category === "security") humanReasons.push("security ticket");
if (confidence < CONFIDENCE_GATE) humanReasons.push("confidence below " + CONFIDENCE_GATE);

return {
  json: {
    from: ticket.from,
    subject: ticket.subject,
    body: ticket.body,
    category,
    priority,
    affected_system: String(raw.affected_system || "unknown"),
    summary: String(raw.summary || ""),
    confidence,
    needs_human: humanReasons.length > 0,
    human_reasons: humanReasons,
    reasoning: String(raw.reasoning || ""),
    validation_ok: valid,
    validation_problems: problems,
    prompt_version: PROMPT_VERSION
  }
};
